import { test, expect } from '@playwright/test';

test.describe('File Upload Retry Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/upload');
  });

  test('should display retry button when upload fails', async ({ page }) => {
    // Create a mock file
    const fileName = 'test-file.txt';
    const fileContent = 'This is a test file';

    // Set up route to simulate upload failure
    await page.route('**/api/upload', route => {
      route.abort('failed');
    });

    // Upload file
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);
    await fileInput.setInputFiles({
      name: fileName,
      mimeType: 'text/plain',
      buffer: Buffer.from(fileContent),
    });

    // Click upload button
    const uploadButton = page.getByRole('button', { name: /upload|submit/i });
    await uploadButton.click();

    // Wait for error message and retry button
    const errorMessage = page.getByText(/upload failed|error|failed/i);
    await expect(errorMessage).toBeVisible();

    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });

  test('should retry upload without re-selecting file', async ({ page }) => {
    const fileName = 'test-file.txt';
    const fileContent = 'This is a test file';

    let uploadAttempts = 0;

    // Set up route to fail first time, succeed second time
    await page.route('**/api/upload', route => {
      uploadAttempts++;
      if (uploadAttempts === 1) {
        route.abort('failed');
      } else {
        route.continue();
      }
    });

    // Upload file
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);
    await fileInput.setInputFiles({
      name: fileName,
      mimeType: 'text/plain',
      buffer: Buffer.from(fileContent),
    });

    // Click upload button
    const uploadButton = page.getByRole('button', { name: /upload|submit/i });
    await uploadButton.click();

    // Wait for error and retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Click retry without selecting file again
    await retryButton.click();

    // Verify upload succeeds
    const successMessage = page.getByText(/success|uploaded|complete/i);
    await expect(successMessage).toBeVisible();

    // Verify file input still contains the file
    const fileInputElement = page.getByLabel(/choose file|select file|upload file/i);
    const files = await fileInputElement.inputValue();
    expect(files).toBeTruthy();
  });

  test('should maintain file selection across multiple retry attempts', async ({ page }) => {
    const fileName = 'test-file.txt';
    const fileContent = 'This is a test file';

    let uploadAttempts = 0;

    // Set up route to fail twice, succeed on third attempt
    await page.route('**/api/upload', route => {
      uploadAttempts++;
      if (uploadAttempts < 3) {
        route.abort('failed');
      } else {
        route.continue();
      }
    });

    // Upload file
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);
    await fileInput.setInputFiles({
      name: fileName,
      mimeType: 'text/plain',
      buffer: Buffer.from(fileContent),
    });

    // First upload attempt
    const uploadButton = page.getByRole('button', { name: /upload|submit/i });
    await uploadButton.click();

    // First retry
    let retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
    await retryButton.click();

    // Second retry
    retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
    await retryButton.click();

    // Verify final success
    const successMessage = page.getByText(/success|uploaded|complete/i);
    await expect(successMessage).toBeVisible();

    // Verify we made exactly 3 upload attempts
    expect(uploadAttempts).toBe(3);
  });
});
